class Solution:
    def sumSubarrayMins(self, arr: list[int]) -> int:
        mod = 10 ** 9 + 7
        ans = 0
        n = len(arr)
        for i in range(n):
            mn = arr[i]
            for j in range(i, n):
                mn = min(mn, arr[j])
                ans = (ans + mn) % mod
        return ans

