class Solution:
    def sumSubarrayMins(self, arr: list[int]) -> int:
        mod = 10 ** 9 + 7
        n = len(arr)
        ans = 0
        for i in range(n):
            left = i
            while left - 1 >= 0 and arr[left - 1] > arr[i]:
                left -= 1
            right = i
            while right + 1 < n and arr[right + 1] >= arr[i]:
                right += 1
            ans = (ans + arr[i] * (i - left + 1) * (right - i + 1)) % mod
        return ans

